def map_groups(items, mapper, reducer):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if not callable(mapper) or not callable(reducer):
        raise TypeError("mapper and reducer must be callable")

    grouped = {}
    order = []
    for item in items:
        emissions = mapper(item)
        if isinstance(emissions, (str, bytes)):
            raise TypeError("emissions must be an iterable of pairs")
        try:
            iterator = iter(emissions)
        except TypeError as exc:
            raise TypeError("emissions must be iterable") from exc
        for emission in iterator:
            if not isinstance(emission, (tuple, list)) or len(emission) != 2:
                raise TypeError("each emission must be a pair")
