                raise TypeError("keys must be hashable") from exc
            if key not in grouped:
                grouped[key] = []
                order.append(key)
            grouped[key].append(deepcopy(value))

    result = []
    for key in sorted(grouped):
        reduced = reducer(key, deepcopy(grouped[key]))
        result.append((deepcopy(key), deepcopy(reduced)))
    return result
