import unittest
from solution import map_groups


class MapGroupsTests(unittest.TestCase):
    def test_first_emission_order_with_incomparable_keys(self):
        items = [1, 2]

        def mapper(item):
            if item == 1:
                return [("z", [1]), (3, [2]), ("z", [3])]
            return [(3, [4]), ((1,), [5])]

        calls = []
        def reducer(key, values):
            calls.append((key, values))
            return [v[0] for v in values]

        result = map_groups(items, mapper, reducer)
        self.assertEqual(result, [("z", [1, 3]), (3, [2, 4]), ((1,), [5])])
        self.assertEqual([call[0] for call in calls], ["z", 3, (1,)])

    def test_values_are_copied_before_storage_and_reducer(self):
        emitted = {"items": [1]}
        reducer_values = []

        def mapper(_):
            return [("key", emitted)]

        def reducer(key, values):
            reducer_values.append(values)
            values[0]["items"].append(2)
            return {"received": values}

        result = map_groups([0], mapper, reducer)
        self.assertEqual(emitted, {"items": [1]})
        reducer_values[0][0]["items"].append(3)
        self.assertEqual(result, [("key", {"received": [{"items": [1, 2]}]})])
        result[0][1]["received"][0]["items"].append(4)
        self.assertEqual(emitted, {"items": [1]})

    def test_mapper_iterables_and_empty_results(self):
        self.assertEqual(map_groups([], lambda x: [(x, x)], lambda k, v: v), [])
        self.assertEqual(map_groups([1], lambda x: iter(()), lambda k, v: v), [])
        self.assertEqual(
            map_groups([1], lambda x: (("a", 2) for _ in range(1)), lambda k, v: sum(v)),
            [("a", 2)],
        )

    def test_input_and_emission_validation(self):
        with self.assertRaises(TypeError):
            map_groups((), lambda x: [], lambda k, v: v)
        with self.assertRaises(TypeError):
            map_groups([], None, lambda k, v: v)
        with self.assertRaises(TypeError):
            map_groups([], lambda x: [], None)
        bad_emissions = ["ab", b"ab", None, [1], [("a",)], [["a", 1, 2]], [([], 1)]]
        for emissions in bad_emissions:
            with self.subTest(emissions=emissions):
                with self.assertRaises(TypeError):
                    map_groups([0], lambda x, e=emissions: e, lambda k, v: v)

    def test_callback_exceptions_propagate(self):
        class MarkerError(Exception):
            pass

        def bad_mapper(_):
            raise MarkerError("mapper")

        with self.assertRaisesRegex(MarkerError, "mapper"):
            map_groups([1], bad_mapper, lambda k, v: v)

        def bad_reducer(key, values):
            raise MarkerError("reducer")

        with self.assertRaisesRegex(MarkerError, "reducer"):
            map_groups([1], lambda x: [("k", x)], bad_reducer)


if __name__ == "__main__":
    unittest.main()

